import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Feature Auctions — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"feature-auctions-02-how-tos-and-workflows.md","filePath":"feature-auctions-02-how-tos-and-workflows.md"}'),i={name:"feature-auctions-02-how-tos-and-workflows.md"};function n(s,e,l,u,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="feature-auctions-—-how-tos-workflows" tabindex="-1">Feature Auctions — How-tos &amp; Workflows <a class="header-anchor" href="#feature-auctions-—-how-tos-workflows" aria-label="Permalink to &quot;Feature Auctions — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Feature Auction workflows</em></p><hr><h2 id="creating-a-feature-auction" tabindex="-1">Creating a Feature Auction <a class="header-anchor" href="#creating-a-feature-auction" aria-label="Permalink to &quot;Creating a Feature Auction&quot;">​</a></h2><p>Any workspace member can create a Feature Auction. The creation flow has five steps.</p><h3 id="step-1-auction-details" tabindex="-1">Step 1: Auction Details <a class="header-anchor" href="#step-1-auction-details" aria-label="Permalink to &quot;Step 1: Auction Details&quot;">​</a></h3><ol><li>Navigate to the Feature Auctions module.</li><li>Click to create a new auction.</li><li>Enter the following: <ul><li><strong>Auction Name</strong> (required)</li><li><strong>Auction Description</strong> (optional — shown to buyers on the auction page)</li><li><strong>Start Date and Time</strong> (required)</li><li><strong>End Date and Time</strong> (required)</li></ul></li></ol><h3 id="step-2-select-features" tabindex="-1">Step 2: Select Features <a class="header-anchor" href="#step-2-select-features" aria-label="Permalink to &quot;Step 2: Select Features&quot;">​</a></h3><ol start="4"><li>Select the Features you want to include from your backlog. Only Features can be auction items.</li></ol><blockquote><p><strong>Important:</strong> The Feature list is locked once the auction is created. You cannot add or remove Features after creation, so make sure your selection is final before proceeding.</p></blockquote><h3 id="step-3-set-pricing" tabindex="-1">Step 3: Set Pricing <a class="header-anchor" href="#step-3-set-pricing" aria-label="Permalink to &quot;Step 3: Set Pricing&quot;">​</a></h3><ol start="5"><li>Set a price for each Feature. Prices represent relative weight — a higher-priced Feature costs buyers more of their budget to prioritize.</li></ol><p>There are no fixed rules for pricing. A common approach is to price Features proportionally to their perceived complexity or strategic weight, so that buyers feel the tradeoff between big bets and smaller wins.</p><h3 id="step-4-add-buyers" tabindex="-1">Step 4: Add Buyers <a class="header-anchor" href="#step-4-add-buyers" aria-label="Permalink to &quot;Step 4: Add Buyers&quot;">​</a></h3><ol start="6"><li>Invite buyers by entering their email addresses.</li><li>Assign each buyer a wallet amount. Different buyers can receive different amounts — use this to weight stakeholder input as needed.</li></ol><blockquote><p><strong>Important:</strong> The buyer list is locked once the auction is created. You cannot add new buyers after the auction has started, so confirm your list before proceeding.</p></blockquote><h3 id="step-5-review-and-create" tabindex="-1">Step 5: Review and Create <a class="header-anchor" href="#step-5-review-and-create" aria-label="Permalink to &quot;Step 5: Review and Create&quot;">​</a></h3><ol start="8"><li>Review all details — Features, prices, buyers, and wallet amounts.</li><li>Create the auction. Invitation emails are sent to all buyers automatically.</li></ol><hr><h2 id="managing-an-active-auction" tabindex="-1">Managing an Active Auction <a class="header-anchor" href="#managing-an-active-auction" aria-label="Permalink to &quot;Managing an Active Auction&quot;">​</a></h2><p>Once an auction is running, you manage it from the Auctioneer Dashboard.</p><h3 id="monitoring-participation" tabindex="-1">Monitoring participation <a class="header-anchor" href="#monitoring-participation" aria-label="Permalink to &quot;Monitoring participation&quot;">​</a></h3><p>The dashboard shows live results per Feature — total spend and quantity purchased — as well as a buyer participation summary showing who has and hasn&#39;t engaged. Use the manual refresh to pull the latest data.</p><h3 id="extending-or-shortening-the-auction" tabindex="-1">Extending or shortening the auction <a class="header-anchor" href="#extending-or-shortening-the-auction" aria-label="Permalink to &quot;Extending or shortening the auction&quot;">​</a></h3><p>You can adjust the end date and time from the dashboard if you need more time for participation or want to close early.</p><h3 id="cancelling-an-auction" tabindex="-1">Cancelling an auction <a class="header-anchor" href="#cancelling-an-auction" aria-label="Permalink to &quot;Cancelling an auction&quot;">​</a></h3><p>You can cancel an auction that&#39;s in progress from the dashboard. Use this if the auction needs to be restarted with different parameters.</p><h3 id="resending-an-invitation" tabindex="-1">Resending an invitation <a class="header-anchor" href="#resending-an-invitation" aria-label="Permalink to &quot;Resending an invitation&quot;">​</a></h3><p>If a buyer missed or lost their invitation email, you can resend the link directly from the dashboard.</p><hr><h2 id="the-buyer-experience" tabindex="-1">The Buyer Experience <a class="header-anchor" href="#the-buyer-experience" aria-label="Permalink to &quot;The Buyer Experience&quot;">​</a></h2><p>Buyers receive an email invitation with a unique link to the auction page. They do not need a Lodestone account.</p><p>On the auction page, buyers see:</p><ul><li>A grid of all available Features</li><li>Their remaining wallet balance</li></ul><p>Clicking a Feature opens a modal with more detail. If an Opportunity Canvas has been generated for that Feature, it is shown here — giving buyers context for what they&#39;re spending on.</p><p>Buyers can purchase multiple quantities of the same Feature, revise their purchases, and change their allocations at any time before the auction ends. Their wallet balance updates in real time as they spend.</p><p>Buyers only see their own activity — they cannot see other buyers&#39; purchases or aggregate spend across the auction.</p><p>Buyers also receive a reminder email before the auction closes.</p><hr><h2 id="interpreting-and-sharing-results" tabindex="-1">Interpreting and Sharing Results <a class="header-anchor" href="#interpreting-and-sharing-results" aria-label="Permalink to &quot;Interpreting and Sharing Results&quot;">​</a></h2><p>When the auction ends, results are available in the Auctioneer Dashboard. Results show a ranked list of Features by:</p><ul><li><strong>Total dollars spent</strong> — reflects how much overall budget was directed toward each Feature</li><li><strong>Quantity purchased</strong> — reflects how many buyers chose to spend on each Feature</li></ul><p>Results are only visible to the auctioneer. To share them with buyers or other stakeholders, export the results as a CSV and distribute manually.</p><h3 id="how-to-use-the-results" tabindex="-1">How to use the results <a class="header-anchor" href="#how-to-use-the-results" aria-label="Permalink to &quot;How to use the results&quot;">​</a></h3><p>Auction results are a signal, not a decision. Common ways to use them:</p><ul><li><strong>Surface surprises</strong> — are stakeholders prioritizing something you hadn&#39;t expected?</li><li><strong>Validate assumptions</strong> — does the auction confirm what your roadmap already reflects, or does it challenge it?</li><li><strong>Fuel a conversation</strong> — share the results in a roadmap review or strategy session to open up a discussion about priorities</li><li><strong>Inform planning</strong> — use the ranked output as one input alongside your own evaluation frameworks and strategic context</li></ul><blockquote><p><strong>Reminder:</strong> Results do not automatically update any Feature, Roadmap, or Strategy in Lodestone. Any changes to your plans based on auction results are made manually.</p></blockquote><hr><h2 id="viewing-past-auctions" tabindex="-1">Viewing Past Auctions <a class="header-anchor" href="#viewing-past-auctions" aria-label="Permalink to &quot;Viewing Past Auctions&quot;">​</a></h2><p>Completed auctions are saved and remain accessible after they end. You can return to any past auction to review results, export the CSV again, or reference the buyer participation summary.</p><hr><p><em>Next: Advanced Features &amp; Customization — wallet strategy, pricing approaches, and getting the most from auction design.</em></p>',52)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
